        ('school', 'story', 2, {'en': 'First Library Card', 'pl': 'Pierwsza karta biblioteczna', 'fr': 'First Library Card'}, ['Mia visite la bibliothèque pour la première fois.', "Elle choisit un petit livre d'aventure.", 'La bibliothécaire lui donne une carte.', 'Mia lit dans le bus du retour.'], ['Mia pierwszy raz idzie do biblioteki.', 'Wybiera cienką książkę przygodową.', 'Bibliotekarka daje jej kartę.', 'Mia czyta w autobusie do domu.'], ['Mia visits the library for the first time.', 'She chooses a thin adventure book.', 'The librarian gives her a card.', 'Mia reads on the bus home.'], [{'word': 'la bibliothèque', 'gloss': {'pl': 'biblioteka', 'en': 'library'}, 'pos': 'noun'}, {'word': 'le livre', 'gloss': {'pl': 'książka', 'en': 'book'}, 'pos': 'noun'}, {'word': 'card', 'gloss': {'pl': 'karta', 'en': 'card'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'What book does Mia choose?', 'pl': 'Jaką książkę wybiera Mia?'}, 'acceptedAnswers': {'en': ['adventure book'], 'pl': ['książkę przygodową']}, 'explanation': {'en': 'She chooses an adventure book.', 'pl': 'Wybiera książkę przygodową.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'Where does she read?', 'pl': 'Gdzie czyta?'}, 'acceptedAnswers': {'en': ['on the bus'], 'pl': ['w autobusie']}, 'explanation': {'en': 'She reads on the bus home.', 'pl': 'Czyta w autobusie do domu.'}}),
